package com.stocksense.warehouse; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="warehouse_locations") @Getter @Setter @NoArgsConstructor public class Location { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Warehouse warehouse; @Column(nullable=false) private String name; @Column(nullable=false) private String code; }